  Curn_TId       BIGINT Default 1,                 -- العملة إلى
  Curn_TRate     NUMERIC(25,9) Default 1,              -- سعر الصرف إلى
  TCAmt          NUMERIC(25,2) Default 0,              -- المبلغ عملة إلى
  TAmt           NUMERIC(25,2) Default 0,              -- المبلغ محلي إلى
  TExCAmt        NUMERIC(25,2) Default 0,              -- المبلغ المنفذ عملة إلى
  TExAmt         NUMERIC(25,2) Default 0,              -- المبلغ المنفذ محلي إلى
  FCCom          NUMERIC(25,2) Default 0,              -- العمولة عملة من
  FCom           NUMERIC(25,2) Default 0,              -- العمولة محلي من
  TCCom          NUMERIC(25,2) Default 0,              -- العمولة عملة الى
  TCom           NUMERIC(25,2) Default 0,              -- العمولة محلي الى
  ExFCCom        NUMERIC(25,2) Default 0,              -- العمولة فعلي عملة من
  ExFCom         NUMERIC(25,2) Default 0,              -- العمولة فعلي محلي من
  ExTCCom        NUMERIC(25,2) Default 0,              -- العمولة فعلي عملة الى
  ExTCom         NUMERIC(25,2) Default 0,              -- العمولة فعلي محلي الى
  Status_Id      BIGINT Default 0,                 -- الحالة
  Status_Date    TIMESTAMP,                                -- التاريخ
  Status_Descr   VARCHAR(100),                  -- الشرح
  MNum           VARCHAR(30),                   -- رقم الشيك\التحويل المصرفي\الحوالة الهاتفية\التحويل
  MDate          TIMESTAMP,                                -- تاريخ الشيك\التحويل المصرفي\الحوالة الهاتفية\التحويل
  Bank_FId       BIGINT,                           -- البنك
  Bank_TId       BIGINT,                           -- البنك
  City_Id        BIGINT Default 0,                 -- المدينة
  PhnBy          INTEGER Default 0,                 -- شركة التحويل
  Correspondent  VARCHAR(100),                  -- المراسل correspondent
  Recipient      VARCHAR(200),                  -- المستلم
  TStatus_Id     BIGINT Default 2,                 -- مؤشر تنفيذ التحويل
  TDate          TIMESTAMP,                                -- تاريخ و وقت إنشاء ورقة التحويل
  TNote          VARCHAR(250),                  --  ملاحظات التحويل
  DCust          VARCHAR(250),                  -- اسم الزبون الذي سيظهر على الإيصال
  Reason         VARCHAR(250),                  -- السبب
  Rem            VARCHAR(250),                  -- ملاحظات
  Ins_User       BIGINT, Ins_Date   TIMESTAMP,
  Upd_User       BIGINT, Upd_Date   TIMESTAMP,
  CONSTRAINT     Bank_TOrd_PK         Primary Key (Id),
  CONSTRAINT     Bank_TOrd_Num_UK     Unique      (Dept_Id, Unit_Id, Period_Id, Num)
);

CREATE SEQUENCE IF NOT EXISTS Bank_TOrdStatus_Seq
  INCREMENT BY 1
  START WITH 1;

Create Table Bank_TOrdStatus                       -- جدول تبدل حالات الأمر
( Id         BIGINT NOT NULL,                     -- مفتاح رئيسي
  Ord_Id     BIGINT NOT NULL,                      -- مفتاح الأب
  Status_Id  BIGINT Default 0,                     -- الحالة
  dDate      TIMESTAMP,                                    -- التاريخ
  Rem        VARCHAR(250),                      -- البيان
  Ins_User   BIGINT,  Ins_Date  TIMESTAMP,
  Upd_User   BIGINT,  Upd_Date  TIMESTAMP,
  CONSTRAINT Bank_TOrdStatus_PK        Primary Key (Id)
);
